create type public.organization_role as enum ('OWNER','ADMIN','MEMBER','VIEWER');
create type public.monitor_status as enum ('UP','DEGRADED','DOWN','PAUSED');
create type public.incident_status as enum ('INVESTIGATING','IDENTIFIED','MONITORING','RESOLVED');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, plan text not null default 'FREE', created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid references public.organizations on delete cascade, user_id uuid references auth.users on delete cascade, role organization_role not null default 'MEMBER', created_at timestamptz not null default now(), primary key(organization_id,user_id));
create table public.monitors (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, url text not null, type text not null check(type in ('WEBSITE','API')), method text not null, interval_seconds int not null check(interval_seconds>=60), timeout_ms int not null, expected_status int not null, response_threshold_ms int not null, failures_before_incident int not null default 2, successes_before_recovery int not null default 2, encrypted_headers jsonb not null default '{}', status monitor_status not null default 'UP', consecutive_failures int not null default 0, consecutive_successes int not null default 0, next_check_at timestamptz not null default now(), locked_at timestamptz, last_checked_at timestamptz, created_at timestamptz not null default now());
create table public.monitor_checks (id bigint generated always as identity primary key, monitor_id uuid not null references public.monitors on delete cascade, status monitor_status not null, http_status int, response_time_ms int not null, error_code text, created_at timestamptz not null default now());
create table public.incidents (id uuid primary key default gen_random_uuid(), monitor_id uuid not null references public.monitors on delete cascade, organization_id uuid not null references public.organizations on delete cascade, title text not null, cause text, status incident_status not null default 'INVESTIGATING', started_at timestamptz not null default now(), resolved_at timestamptz, created_at timestamptz not null default now());
create table public.incident_updates (id uuid primary key default gen_random_uuid(), incident_id uuid not null references public.incidents on delete cascade, author_id uuid references auth.users, status incident_status, body text not null, created_at timestamptz not null default now());
create index monitors_due_idx on public.monitors(next_check_at) where status!='PAUSED'; create index checks_monitor_created_idx on public.monitor_checks(monitor_id,created_at desc); create index incidents_org_status_idx on public.incidents(organization_id,status,started_at desc);
alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.monitors enable row level security; alter table public.monitor_checks enable row level security; alter table public.incidents enable row level security; alter table public.incident_updates enable row level security;
create function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid()) $$;
create function public.can_manage_org(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid() and role in ('OWNER','ADMIN','MEMBER')) $$;
create policy "members read org" on public.organizations for select using(public.is_org_member(id)); create policy "members read membership" on public.organization_members for select using(public.is_org_member(organization_id));
create policy "members read monitors" on public.monitors for select using(public.is_org_member(organization_id)); create policy "managers insert monitors" on public.monitors for insert with check(public.can_manage_org(organization_id)); create policy "managers update monitors" on public.monitors for update using(public.can_manage_org(organization_id)); create policy "admins delete monitors" on public.monitors for delete using(public.can_manage_org(organization_id));
create policy "members read checks" on public.monitor_checks for select using(exists(select 1 from public.monitors m where m.id=monitor_id and public.is_org_member(m.organization_id)));
create policy "members read incidents" on public.incidents for select using(public.is_org_member(organization_id)); create policy "managers update incidents" on public.incidents for update using(public.can_manage_org(organization_id));
